func (rs *ResolutionService) Submit(signal *ResolutionSignal) bool {
	rs.statsMu.Lock()
	rs.stats.TotalSignals++
	rs.statsMu.Unlock()

	select {
	case rs.signalChan <- signal:
		return true
	default:
		rs.statsMu.Lock()
		rs.stats.DroppedSignals++
		rs.statsMu.Unlock()
		return false
	}
}
```

