func (m *BadgeWASMMapper) LookupWASM(badgeID, tag string) (string, WASMType, error) {
	m.mu.RLock()
	defer m.mu.RUnlock()

	entry, ok := m.entries[badgeID]
	if !ok {
		return "", "", fmt.Errorf("badge %s not registered", badgeID)
	}
	for _, mp := range entry.Mappings {
		if strings.EqualFold(mp.Tag, tag) {
			if mp.WASMPath == "" {
				return "", mp.WASMType, fmt.Errorf("no WASM module for tag %s on badge %s", tag, badgeID)
			}
			return mp.WASMPath, mp.WASMType, nil
		}
	}
	return "", "", fmt.Errorf("tag %s not found on badge %s", tag, badgeID)
}
